    std::size_t last = 0;
    for (std::size_t x = 0; x < row.size(); ++x)
        if (!row[x].blank()) last = x + 1;

    // Does this row contain any filled-block glyph? If so, render EVERY cell as
    // a fixed 1ch inline-block (blocks as geometry, others as a 1ch text cell)
    // so nothing can kern and the row is exactly last×1ch wide. Mixing inline
    // text with inline-block cells reintroduces sub-pixel drift, so it's all or
    // nothing per row — and only logo rows pay the per-cell cost.
    bool has_block = false;
    for (std::size_t x = 0; x < last; ++x)
        if (!row[x].cont && !row[x].ch.empty() && !block_bg(first_cp(row[x].ch), 0xffffff).empty())
            { has_block = true; break; }

    if (has_block) {
        for (std::size_t x = 0; x < last; ++x) {
            if (row[x].cont) continue;
            const grid::Style st = style_of(row[x].style);
            const bool inv = (st.attrs & grid::attr::Inverse) != 0;
            std::uint32_t fg = pal.resolve(st.fg, false);
            std::uint32_t bg = pal.resolve(st.bg, true);
            if (inv) std::swap(fg, bg);
            char32_t cp = first_cp(row[x].ch);
            std::string bgv = row[x].ch.empty() ? std::string{} : block_bg(cp, fg);
            auto k = detail_dom::span_key(y, static_cast<int>(x));
            if (!bgv.empty()) { out.push_back(block_cell(cp, fg, lh, k)); continue; }
            // Non-block cell in a block row: a fixed 1ch text cell.
            auto cell = text(row[x].ch.empty() ? std::string(" ") : row[x].ch)
                      | detail_dom::fg_hex(fg)
                      | detail::raw_css("display", "inline-block")
                      | detail::raw_css("width", "1ch")
                      | detail::raw_css("text-align", "center")
                      | key(k);
            out.push_back(std::move(cell));
        }
        out.push_back(text("\n") | key("nl" + std::to_string(y)));
        return;
    }

    // Plain text row: coalesce runs (fast path, ~6 spans/row).
    std::size_t x = 0;
    while (x < last) {
        const std::uint16_t sid = row[x].style;
        const grid::Style st = style_of(sid);
        const bool inverse = (st.attrs & grid::attr::Inverse) != 0;
        std::uint32_t fg = pal.resolve(st.fg, false);
        std::uint32_t bg = pal.resolve(st.bg, true);
        if (inverse) std::swap(fg, bg);
        const bool paint_bg = (st.bg.kind != grid::Color::Kind::Default) || inverse;

        const std::size_t start = x;
        std::string tx;
        while (x < last && row[x].style == sid) {
            const auto& c = row[x];
            if (c.cont) { ++x; continue; }
            tx += c.ch.empty() ? " " : c.ch;
            ++x;
        }
        if (tx.empty()) { if (x == start) ++x; continue; }

        auto span = text(tx) | detail_dom::fg_hex(fg)
                  | detail::raw_css("white-space", "pre");
        if (paint_bg)                         span = span | detail_dom::bg_hex(bg);
        if (st.attrs & grid::attr::Bold)      span = span | bold;
        if (st.attrs & grid::attr::Italic)    span = span | italic;
        if (st.attrs & grid::attr::Underline) span = span | underline;
        if (st.attrs & grid::attr::Dim)       span = span | opacity(0.55f);
        if (st.attrs & grid::attr::Conceal)   span = span | opacity(0.f);
        span = span | key(detail_dom::span_key(y, static_cast<int>(start)));
        out.push_back(std::move(span));
    }
    out.push_back(text("\n") | key("nl" + std::to_string(y)));
}

